      braking: trackItem.type==='drift' ? 'РџРѕ РёРЅРµСЂС†РёРё / СЂСѓС‡РЅРёРє РїРѕ РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё' : ['150вЂ“120 Рј','120вЂ“90 Рј','100вЂ“70 Рј','90вЂ“60 Рј','120вЂ“80 Рј'][index],
